// TH16 v1.00a Stage 1 midboss MBoss (st01mbs.ecl.txt MBoss/MBoss1/MBoss1_at).
// Source timing: st01 main:1529 creates MBoss; timerReset at entry; setInterrupt 1020 frames.
const TIME_LIMIT: int = 1144;   // 120 shell buffer + 1020 source window + 4 start margin
const OPENING_BUFFER: int = 120;

// TH16 v1.00a type aliases used by this card (transcribe/th16/touhou-bullets.ecl).
const TH16_BALL: int = 416;        // type 4,  r=4
const TH16_RICE: int = 480;        // type 8,  r=2.4
const TH16_BIG_BALL: int = 640;    // type 18, r=8.5
const TH16_BUBBLE: int = 864;      // type 32, r=14

// ---------------------------------------------------------------------------
// Shell: control owns the non-spell phase; the real MBoss is a separate enemy.
// ---------------------------------------------------------------------------
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(192fx, -32fx, 5200, 0, 0, 0, source_enemy);
}

// ---------------------------------------------------------------------------
// MBoss entry (st01mbs.ecl.txt:6-40)
// ---------------------------------------------------------------------------
async sub source_enemy() {
    set_invuln(65535);
    set_hurtbox(24fx);                              // setHurtbox(48,48): 48*0.5
    set_hitbox(20fx);                               // setHitbox(40,40): 40*0.5

    // enmCreate("Ecl_EtBreak_ni",0,0) at the pre-move position (192,-32):
    // expanding bullet clear wave, default.ecl.txt:174-190.
    spawn et_break_clear(192fx, -32fx);

    move_to(0, 192fx, -64fx, EASE_LINEAR);          // movePos(192,-64)
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);        // movePosTime(100,4,0,128)
    wait(40);
    // moveLimit(0,128,280,256) is enforced per step by card_arm_next_step.

    // MBoss1 (st01mbs.ecl.txt:42-74). EffChargePoint3 is pure ANM/sound.
    var layers: int = global(GVAR_RANK) + 3;        // diffI($I0,3,4,5,6)
    var w: int = 120;
    if global(GVAR_RANK) >= 2 { w = 60; }           // !E/!N 120; !H/!LO 60
    wait(80);
    loop {
        spawn mboss1_at(80deg, -17deg, layers);     // MBoss1_at(1.3962634,-0.29670596)
        card_wait(w);
        move_rand();                                // moveRand(60,4,1.0)
        card_wait(w);
    }
}

// Ecl_EtBreak_ni: etClear(16) then +10 per frame while radius < 640.
async sub et_break_clear(cx: fx, cy: fx) {
    for k in 0..63 {
        clear_bullets_at(cx, cy, (16 + k * 10) as fx, 0);
        wait(1);
    }
}

// ---------------------------------------------------------------------------
// MBoss1_at (st01mbs.ecl.txt:76-161)
// ---------------------------------------------------------------------------
async sub mboss1_at(spread0: angle, delta: angle, layers: int) {
    var rank: int = global(GVAR_RANK);

    // Emitter 0: fixed-direction fan, type8/color10, 6 bursts every 6 frames.
    var count: int = 4;                             // !E 4; !N 4; !H 4; !LO 6
    if rank == 3 { count = 6; }
    var s0: fx = 1.5fx;                             // etSpeed s0 by difficulty
    if rank == 1 { s0 = 2.5fx; }
    if rank == 2 { s0 = 3.5fx; }
    if rank == 3 { s0 = 4.1fx; }
    var step: fx = (1fx - s0) / (layers - 1);       // etSpeed s1 = 1.0, M-1 steps
    var spread: angle = spread0;
    for burst in 0..6 {                             // $E = 5 -> 6 bursts
        var s: int = spread as int;
        for q in 0..layers {
            var v: fx = s0 + (q as fx) * step;
            var back: fx = 4fx * v;                 // ANIM birth retreat: -4*velocity
            for i in 0..count {
                // fixed fan: alpha + F(N,i), alpha = 90deg
                var off: int = i * s - ((count - 1) * s) / 2;
                var ang: angle = 90deg + (off as angle);
                _ = fire(TH16_RICE, 10, $self_x - back * cos(ang), $self_y - back * sin(ang),
                         v, ang, none, none);
            }
        }
        spread = spread + delta;                    // %A += %B
        wait(6);
    }
    wait(80);

    // Emitter 1: single fixed shot every 6 frames; !NHL skips firing on Easy.
    var shape: int = TH16_BALL;                     // etSprite(1,[-1],[-2]) by difficulty
    var color: int = 10;
    if rank == 2 { shape = TH16_BIG_BALL; color = 5; }
    if rank == 3 { shape = TH16_BUBBLE; color = 2; }
    var s1: fx = 1.5fx;
    if rank == 2 { s1 = 2.5fx; }
    if rank == 3 { s1 = 4.1fx; }
    var shots: int = 5;                             // diffI($F,5,5,6,6)
    if rank >= 2 { shots = 6; }
    var back1: fx = 4fx * s1;
    if rank != 0 {
        for k in 0..(shots + 1) {
            _ = fire(shape, color, $self_x - back1 * cos(90deg), $self_y - back1 * sin(90deg),
                     s1, 90deg, none, none);
            wait(6);
        }
    } else {
        for j in 0..(shots + 1) { wait(6); }
    }
}

// ---------------------------------------------------------------------------
// moveRand(60,4,1.0) with moveLimit(0,128,280,256) (movement.md recipe).
// Bounds x in [-140,140], y in [0,256]; inner x +-70, y 64..192.
// Shared slots: int0 = step count, fx0/fx1 = unit direction.
// ---------------------------------------------------------------------------
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }      // linear 1 - k/60
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +-pi/2 guard, epsilon 0.05 rad
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
